package com.driveflow.servlet;
import com.driveflow.model.Vehicle; import com.driveflow.store.DataStore; import com.driveflow.util.Flash; import javax.servlet.*; import javax.servlet.http.*; import java.io.IOException;
public class VehicleServlet extends HttpServlet {
 protected void doGet(HttpServletRequest req,HttpServletResponse resp)throws ServletException,IOException{String a=req.getParameter("action"); if("edit".equals(a)){req.setAttribute("editVehicle",DataStore.vehicle(Integer.parseInt(req.getParameter("id"))));req.setAttribute("vehicles",DataStore.vehicles);req.getRequestDispatcher("/views/vehicles.jsp").forward(req,resp);return;} if("delete".equals(a)){int id=Integer.parseInt(req.getParameter("id"));Vehicle v=DataStore.vehicle(id);if(v!=null&&v.getStatus()!=Vehicle.Status.RENTED)DataStore.vehicles.remove(v);Flash.set(req.getSession(),"success","Vehicle removed successfully.");resp.sendRedirect(req.getContextPath()+"/vehicles");return;}req.setAttribute("vehicles",DataStore.vehicles);req.getRequestDispatcher("/views/vehicles.jsp").forward(req,resp);}
 protected void doPost(HttpServletRequest req,HttpServletResponse resp)throws IOException{
  try{String action=req.getParameter("action");String reg=req.getParameter("registrationNo").trim();String brand=req.getParameter("brand").trim();String model=req.getParameter("model").trim();String type=req.getParameter("type");String fuel=req.getParameter("fuelType");int year=Integer.parseInt(req.getParameter("year"));double rate=Double.parseDouble(req.getParameter("dailyRate"));Vehicle.Status status=Vehicle.Status.valueOf(req.getParameter("status"));
   if("edit".equals(action)){Vehicle v=DataStore.vehicle(Integer.parseInt(req.getParameter("id")));if(v==null)throw new IllegalArgumentException("Vehicle not found.");v.setRegistrationNo(reg);v.setBrand(brand);v.setModel(model);v.setType(type);v.setFuelType(fuel);v.setYear(year);v.setDailyRate(rate);if(v.getStatus()!=Vehicle.Status.RENTED)v.setStatus(status);Flash.set(req.getSession(),"success","Vehicle updated successfully.");}
   else {for(Vehicle v:DataStore.vehicles)if(v.getRegistrationNo().equalsIgnoreCase(reg))throw new IllegalArgumentException("Registration number already exists.");DataStore.vehicles.add(new Vehicle(DataStore.nextVehicleId(),reg,brand,model,type,fuel,year,rate,status));Flash.set(req.getSession(),"success","Vehicle added successfully.");}
  }catch(Exception e){Flash.set(req.getSession(),"error","Could not save vehicle: "+e.getMessage());}resp.sendRedirect(req.getContextPath()+"/vehicles");
 }
}
